<script setup>
import {ref,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue'
import {RefreshCw,Activity,ShieldCheck} from 'lucide-vue-next'
import {voiceApi,stamp} from '../voice/operations'
const OperationDiagnosticsPanel=defineAsyncComponent(()=>import('./OperationDiagnosticsPanel.vue'))
const state=ref(null),form=ref(null),error=ref(''),notice=ref(''),busy=ref(false)
let timer
async function api(path='',method='GET',data){return voiceApi('/health'+path,method,data)}
async function load(){state.value=await api()}
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function edit(){form.value={...state.value.policy,paused:!!state.value.policy.paused}}
async function save(){await api('/policy','PUT',form.value);form.value=null;notice.value='Limites salvos. Chamadas em andamento foram preservadas.';await load()}
onMounted(()=>{run(load);timer=setInterval(()=>{if(!busy.value)load().catch(e=>error.value=e.message)},30000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><section class="health"><span class="eyebrow">VISIBILIDADE PARA OPERAR</span><div class="heading"><div><h1>Saúde e limites</h1><p>Disponibilidade, consumo conhecido e pendências que exigem conferência.</p></div><button class="secondary" @click="run(load)"><RefreshCw :size="15"/>Atualizar</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="state"><p v-if="state.policy.paused" class="error">Novas chamadas e mensagens estão pausadas pela supervisão.</p><div class="stats"><article class="table-card"><span>Chamadas no dia UTC</span><strong>{{state.counts.calls_today}} <small>/ {{state.limits.voice_daily}}</small></strong><progress :value="state.counts.calls_today" :max="state.limits.voice_daily"/></article><article class="table-card"><span>WhatsApp no dia UTC</span><strong>{{state.counts.messages_today}} <small>/ {{state.limits.whatsapp_daily}}</small></strong><progress :value="state.counts.messages_today" :max="state.limits.whatsapp_daily"/></article><article class="table-card"><span>Chamadas reservadas / ativas</span><strong>{{state.counts.active_calls}}</strong><small>Capacidade homologação: {{state.limits.external_concurrency}}</small></article><article class="table-card"><span>Mensagens sem confirmação</span><strong>{{state.counts.messages_unknown}}</strong><small>{{state.counts.webhooks_dead}} eventos com entrega esgotada</small></article></div><p>{{state.limits.note}} Contagem diária: {{state.day_utc}} UTC.</p><div class="columns"><article class="table-card box"><h2>Equipe agora</h2><table><thead><tr><th>Atendente</th><th>Estado</th><th>Último sinal</th></tr></thead><tbody><tr v-for="u in state.team"><td>{{u.name}}</td><td>{{u.busy?'Em atendimento / tabulação':!u.voice_enabled?'Desativado':!u.online?'Offline':u.status==='available'?'Disponível':'Pausado'}}</td><td>{{stamp(u.last_seen_at)}}</td></tr></tbody></table></article><article class="table-card box"><h2>Custos conhecidos</h2><div v-for="c in state.costs.known" class="cost"><strong>{{Number(c.amount).toFixed(4)}} {{c.currency.toUpperCase()}}</strong><small>{{c.legs}} pernas conciliadas</small></div><p v-if="!state.costs.known.length">Nenhum valor conciliado no período.</p><p>{{state.costs.calls_without_cost}} chamadas de saída sem qualquer custo informado.</p><p v-if="state.costs.alert" class="error">O custo conhecido ultrapassou o alerta configurado.</p><small>{{state.costs.scope}}</small></article></div><article class="table-card box"><div class="heading"><h2>Controles de operação</h2><button v-if="state.can_manage" class="secondary" @click="edit">Editar limites</button></div><p>A pausa bloqueia novas chamadas e envios. Resultados, recebimentos de WhatsApp e encerramentos continuam sendo registrados.</p><form v-if="form" @submit.prevent="run(save)"><label class="check-label"><input type="checkbox" v-model="form.paused">Pausar novos atendimentos e envios</label><div class="columns"><label>Máximo diário de tentativas de voz<input type="number" min="1" max="50" v-model.number="form.voice_daily_limit" required></label><label>Máximo diário de mensagens<input type="number" min="1" max="100" v-model.number="form.whatsapp_daily_limit" required></label><label>Alerta de custo conhecido · USD<input type="number" min="0.01" max="100000" step="0.01" v-model="form.cost_alert_usd" placeholder="Opcional"></label></div><div class="actions"><button class="primary" :disabled="busy">Salvar controles</button><button type="button" class="secondary" @click="form=null">Cancelar</button></div></form></article><article class="table-card box scroll"><h2>Conferência de chamadas</h2><p>Consultar o provedor não repete a chamada. A capacidade só é liberada com encerramento confirmado.</p><table><thead><tr><th>Contato</th><th>Método</th><th>Estado</th><th>Reservada em</th><th></th></tr></thead><tbody><tr v-for="c in state.pending_calls"><td>{{c.destination}}</td><td>{{c.method==='programmable_voice'?'Twilio API':'SIP'}}</td><td>{{c.status}}</td><td>{{stamp(c.created_at)}}</td><td><button v-if="c.method==='programmable_voice'" class="secondary" :disabled="busy" @click="run(async()=>{await api('/calls/'+c.id+'/reconcile','POST',{});await load()})">Consultar provedor</button><span v-else>Conferir no PBX</span></td></tr><tr v-for="c in state.pending_inbound"><td>{{c.from_number}}</td><td>Receptivo</td><td>{{c.status}}</td><td>{{stamp(c.created_at)}}</td><td><button class="secondary" :disabled="busy" @click="run(async()=>{await voiceApi('/inbound/calls/'+c.id+'/reconcile','POST',{});await load()})">Consultar provedor</button></td></tr></tbody></table><p v-if="!state.pending_calls.length&&!state.pending_inbound.length">Nenhuma chamada com capacidade reservada.</p></article><article class="table-card box"><h2>Mensagens que aguardam confirmação</h2><p>O conector QR consulta os resultados existentes. A API Twilio depende de callback ou correlação com o identificador original. Não é feito reenvio automático de mensagens incertas.</p><p v-for="m in state.pending_messages">{{m.to_number}} · {{m.provider}} · {{m.status}} · {{stamp(m.created_at)}}</p><p v-if="!state.pending_messages.length">Nenhuma pendência.</p></article><OperationDiagnosticsPanel/></template></section></template>
<style scoped>.heading,.actions{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.actions{justify-content:flex-start}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:25px 0}.stats article{padding:24px}.health .stats article{display:block;min-width:0}.stats span,.stats small{display:block;font-size:12px;color:#747d6a}.stats strong{display:block;font-size:36px;margin:16px 0}.stats strong small{display:inline;font-size:18px}.stats progress{width:100%;height:8px;accent-color:#c39a3c}.columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.box{padding:24px;margin-bottom:22px}.health p,.health small{color:#727d67;line-height:1.75}.health label:not(.check-label){display:flex;flex-direction:column;gap:8px;font-size:13px;margin:18px 0}.cost{display:flex;flex-direction:column;gap:7px;margin:20px 0}.cost strong{font-size:26px}.scroll{overflow:auto}.box table{font-size:12px}.box h2{font-size:19px}@media(max-width:1000px){.stats{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}}@media(max-width:600px){.health .stats{grid-template-columns:1fr}.stats article{padding:16px}.box{padding:16px;overflow:auto}.stats strong{font-size:28px}}
</style>
